var html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta http-equiv="Content-Security-Policy" content="default-src 'self' 'unsafe-inline' 'unsafe-eval' https: data:;">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0">
<title>Workout Tracker</title>
<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Syne:wght@400;600;700;800&display=swap" rel="stylesheet">
<style>
  :root {
    --bg: #0d0f14;
    --surface: #13161e;
    --surface2: #1a1e28;
    --border: #252a38;
    --accent: #4f9eff;
    --accent2: #00e5a0;
    --text: #e8eaf0;
    --text-dim: #c8ccd8;
    --text-muted: #8b92a8;
    --user-bg: #1e3a5f;
    --user-border: #2d5a9e;
    --bot-bg: #131820;
    --danger: #ff4f6e;
    --warning: #ffb347;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Syne', sans-serif;
    height: 100dvh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  /* -- HEADER -- */
  header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 20px;
    border-bottom: 1px solid var(--border);
    background: var(--surface);
    flex-shrink: 0;
  }

  .logo {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
  }

  .header-text h1 {
    font-size: 16px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--text);
  }

  .header-text p {
    font-size: 11px;
    color: var(--text-dim);
    font-family: 'JetBrains Mono', monospace;
    margin-top: 1px;
  }

  .status-dot {
    width: 8px;
    height: 8px;
    background: var(--accent2);
    border-radius: 50%;
    margin-left: auto;
    box-shadow: 0 0 8px var(--accent2);
    animation: pulse 2s infinite;
  }

  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.4; }
  }

  /* -- MESSAGES -- */
  #messages {
    flex: 1;
    overflow-y: auto;
    padding: 20px 16px;
    display: flex;
    flex-direction: column;
    gap: 16px;
    scroll-behavior: smooth;
  }

  #messages::-webkit-scrollbar { width: 4px; }
  #messages::-webkit-scrollbar-track { background: transparent; }
  #messages::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }

  .message {
    display: flex;
    flex-direction: column;
    max-width: 92%;
    animation: fadeIn 0.3s ease;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .message.user { align-self: flex-end; align-items: flex-end; }
  .message.bot { align-self: flex-start; align-items: flex-start; }

  .message-label {
    font-size: 10px;
    font-family: 'JetBrains Mono', monospace;
    color: var(--text-muted);
    margin-bottom: 4px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .bubble {
    padding: 12px 16px;
    border-radius: 16px;
    font-size: 14px;
    line-height: 1.6;
    word-break: break-word;
  }

  .message.user .bubble {
    background: var(--user-bg);
    border: 1px solid var(--user-border);
    border-bottom-right-radius: 4px;
    color: #c8daff;
  }

  .message.bot .bubble {
    background: var(--bot-bg);
    border: 1px solid var(--border);
    border-bottom-left-radius: 4px;
    color: var(--text);
  }

  /* -- WORKOUT TABLE -- */
  .workout-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 16px;
    border-bottom-left-radius: 4px;
    overflow: hidden;
    max-width: 100%;
  }

  .workout-header {
    padding: 14px 16px;
    border-bottom: 1px solid var(--border);
    background: var(--surface2);
  }

  .workout-header h3 {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 8px;
  }

  .workout-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  .meta-tag {
    font-size: 11px;
    font-family: 'JetBrains Mono', monospace;
    padding: 3px 8px;
    border-radius: 4px;
    background: var(--bg);
    border: 1px solid var(--border);
    color: var(--text-dim);
  }

  .meta-tag span {
    color: var(--accent2);
    font-weight: 600;
  }

  .exercise-list {
    padding: 8px 0;
  }

  .exercise-row {
    display: grid;
    grid-template-columns: 28px 1fr auto;
    align-items: start;
    gap: 10px;
    padding: 12px 16px;
    border-bottom: 1px solid var(--border);
    transition: background 0.15s;
  }

  .ex-details {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 5px;
  }

  .ex-detail-tag {
    font-size: 10px;
    font-family: "JetBrains Mono", monospace;
    padding: 2px 6px;
    border-radius: 3px;
    background: var(--surface2);
    border: 1px solid var(--border);
    color: var(--text-dim);
  }

  .ex-detail-tag span {
    color: var(--text-muted);
    margin-right: 3px;
  }

  .exercise-row:last-child { border-bottom: none; }
  .exercise-row:hover { background: var(--surface2); }

  .ex-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 700;
  }

  .ex-name {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    line-height: 1.3;
  }

  .ex-new {
    font-size: 9px;
    font-family: 'JetBrains Mono', monospace;
    background: rgba(0, 229, 160, 0.1);
    color: var(--accent2);
    border: 1px solid rgba(0, 229, 160, 0.3);
    padding: 1px 5px;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    display: inline-block;
    margin-top: 2px;
  }

  .ex-volume {
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    color: var(--accent);
    text-align: right;
    white-space: nowrap;
  }

  .ex-type {
    font-size: 10px;
    color: var(--text-muted);
    text-align: right;
    margin-top: 1px;
    font-family: 'JetBrains Mono', monospace;
  }

  .workout-footer {
    padding: 12px 16px;
    border-top: 1px solid var(--border);
    background: var(--surface2);
  }

  .reply-options {
    font-size: 11px;
    font-family: 'JetBrains Mono', monospace;
    color: var(--text-dim);
    margin-bottom: 6px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .quick-replies {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 8px;
  }

  .quick-reply {
    font-size: 12px;
    font-family: 'JetBrains Mono', monospace;
    padding: 5px 10px;
    border-radius: 6px;
    background: var(--bg);
    border: 1px solid var(--border);
    color: var(--accent);
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
  }

  .quick-reply:hover {
    background: var(--accent);
    color: var(--bg);
    border-color: var(--accent);
  }

  /* -- TYPING INDICATOR -- */
  .typing {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 12px 16px;
    background: var(--bot-bg);
    border: 1px solid var(--border);
    border-radius: 16px;
    border-bottom-left-radius: 4px;
    width: fit-content;
  }

  .typing span {
    width: 6px;
    height: 6px;
    background: var(--text-muted);
    border-radius: 50%;
    animation: bounce 1.2s infinite;
  }

  .typing span:nth-child(2) { animation-delay: 0.2s; }
  .typing span:nth-child(3) { animation-delay: 0.4s; }

  @keyframes bounce {
    0%, 60%, 100% { transform: translateY(0); }
    30% { transform: translateY(-6px); background: var(--accent); }
  }

  /* -- INPUT -- */
  .input-area {
    padding: 12px 16px;
    border-top: 1px solid var(--border);
    background: var(--surface);
    flex-shrink: 0;
  }

  .input-row {
    display: flex;
    gap: 10px;
    align-items: flex-end;
  }

  #userInput {
    flex: 1;
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 10px 14px;
    color: var(--text);
    font-family: 'Syne', sans-serif;
    font-size: 14px;
    resize: none;
    min-height: 44px;
    max-height: 120px;
    outline: none;
    transition: border-color 0.2s;
    line-height: 1.5;
  }

  #userInput:focus { border-color: var(--accent); }
  #userInput::placeholder { color: var(--text-muted); }

  #sendBtn {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    background: var(--accent);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: all 0.2s;
  }

  #sendBtn:hover { background: #3d8ae0; transform: scale(1.05); }
  #sendBtn:active { transform: scale(0.95); }
  #sendBtn:disabled { background: var(--border); cursor: not-allowed; transform: none; }

  #sendBtn svg { width: 18px; height: 18px; fill: white; }

  /* -- WELCOME -- */
  .welcome {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1;
    gap: 12px;
    padding: 40px 20px;
    text-align: center;
  }

  .welcome-icon {
    width: 64px;
    height: 64px;
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 32px;
    margin-bottom: 8px;
  }

  .welcome h2 {
    font-size: 22px;
    font-weight: 800;
    color: var(--text);
  }

  .welcome p {
    font-size: 14px;
    color: var(--text-dim);
    max-width: 280px;
    line-height: 1.6;
  }

  .welcome-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: center;
    margin-top: 8px;
  }

  .welcome-chip {
    font-size: 12px;
    font-family: 'JetBrains Mono', monospace;
    padding: 6px 12px;
    border-radius: 8px;
    background: var(--surface2);
    border: 1px solid var(--border);
    color: var(--accent);
    cursor: pointer;
    transition: all 0.2s;
  }

  .welcome-chip:hover {
    background: var(--accent);
    color: var(--bg);
    border-color: var(--accent);
  }

  /* -- ERROR -- */
  .error-bubble {
    background: rgba(255, 79, 110, 0.1);
    border: 1px solid rgba(255, 79, 110, 0.3);
    color: #ff8fa3;
    padding: 10px 14px;
    border-radius: 12px;
    font-size: 13px;
    font-family: 'JetBrains Mono', monospace;
  }

  /* -- PLAIN TEXT -- */
  .plain-text {
    white-space: pre-wrap;
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    line-height: 1.7;
  }
</style>
</head>
<body>

<header>
  <div class="logo">💪</div>
  <div class="header-text">
    <h1>Workout Tracker</h1>
    <p>AI-powered workout assistant</p>
  </div>
  <div class="status-dot"></div>
</header>

<div id="messages">
  <div class="welcome" id="welcome">
    <div class="welcome-icon">🏋️</div>
    <h2>Welcome to Workout Tracker</h2>
    <p>Do you want to log or suggest a new workout?</p>
    <div class="welcome-chips">
      <div class="welcome-chip" onclick="sendQuick('Suggest a full body workout')">Suggest workout</div>
      <div class="welcome-chip" onclick="sendQuick('Suggest a lower body workout')">Lower body</div>
      <div class="welcome-chip" onclick="sendQuick('Suggest an upper body workout')">Upper body</div>
      <div class="welcome-chip" onclick="sendQuick('Log a workout')">Log workout</div>
    </div>
  </div>
</div>

<div id="staged-banner" style="display:none;margin:12px 16px 0;padding:12px 16px;background:#1a2035;border:1px solid #2d5a9e;border-radius:12px;align-items:center;gap:10px;flex-shrink:0;">
  <div style="flex:1;font-size:13px;color:#c8daff;font-family:Syne,sans-serif;">
    <span style="font-weight:700;color:#4f9eff;">You have an unsaved workout from earlier.</span><br>
    <span style="font-size:11px;color:#6b7280;">Generated this session  -  not yet confirmed.</span>
  </div>
  <button onclick="viewStagedWorkout()" style="padding:6px 12px;background:#4f9eff;border:none;border-radius:8px;color:white;font-size:12px;font-family:Syne,sans-serif;font-weight:700;cursor:pointer;">View</button>
  <button onclick="dismissStagedWorkout()" style="padding:6px 12px;background:transparent;border:1px solid #404558;border-radius:8px;color:#6b7280;font-size:12px;font-family:Syne,sans-serif;cursor:pointer;">Dismiss</button>
</div>

<div class="input-area">
  <div class="input-row">
    <textarea id="userInput" placeholder="Type a message..." rows="1"></textarea>
    <button id="sendBtn" onclick="sendMessage()">
      <svg viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>
    </button>
  </div>
</div>

<script>
  var WEBHOOK_URL = 'https://YOUR-N8N-HOST/webhook/YOUR-CHAT-WEBHOOK-ID/chat';
  // -- SESSION PERSISTENCE ------------------------------------------
  var STAGED_API_URL = 'https://YOUR-N8N-HOST/webhook/get-staged-workout';

  function generateNewSessionId() {
    return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  }

  var _storage = null;
  try {
    if (typeof localStorage !== 'undefined' && localStorage !== null) {
      localStorage.setItem('_test', '1');
      localStorage.removeItem('_test');
      _storage = localStorage;
    }
  } catch(e) { _storage = null; }

  function safeLocalStorageGet(key) {
    try { return _storage ? _storage.getItem(key) : null; } catch(e) { return null; }
  }

  function safeLocalStorageSet(key, val) {
    try { if (_storage) _storage.setItem(key, val); } catch(e) {}
  }

  function getSessionId() {
    var stored = safeLocalStorageGet('wt_session_id');
    if (stored) return stored;
    var newId = generateNewSessionId();
    safeLocalStorageSet('wt_session_id', newId);
    return newId;
  }

  function resetSession() {
    var newId = generateNewSessionId();
    safeLocalStorageSet('wt_session_id', newId);
    return newId;
  }

  var sessionId = getSessionId();
  var messagesEl = document.getElementById('messages');
  var input = document.getElementById('userInput');
  var sendBtn = document.getElementById('sendBtn');
  var welcomeEl = document.getElementById('welcome');

  // Auto-resize textarea
  input.addEventListener('input', function() {
    this.style.height = 'auto';
    this.style.height = Math.min(this.scrollHeight, 120) + 'px';
  });

  // Send on Enter (Shift+Enter for newline)
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });

  function sendQuick(text) {
    input.value = text;
    sendMessage();
  }

  function hideWelcome() {
    if (welcomeEl) {
      welcomeEl.style.display = 'none';
    }
  }

  function scrollToBottom() {
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  function addUserMessage(text) {
    hideWelcome();
    var div = document.createElement('div');
    div.className = 'message user';
    div.innerHTML = '<div class="message-label">You</div><div class="bubble">' + escapeHtml(text) + '</div>';
    messagesEl.appendChild(div);
    scrollToBottom();
  }

  function addTyping() {
    var div = document.createElement('div');
    div.className = 'message bot';
    div.id = 'typing-indicator';
    div.innerHTML = '<div class="message-label">Workout Tracker</div><div class="typing"><span></span><span></span><span></span></div>';
    messagesEl.appendChild(div);
    scrollToBottom();
    return div;
  }

  function removeTyping() {
    var el = document.getElementById('typing-indicator');
    if (el) el.remove();
  }

  function escapeHtml(text) {
    return text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function parseReplacementSuggestions(text) {
    if (text.indexOf('REPLACEMENT SUGGESTIONS') === -1) return null;
    var lines = text.split('\\n');
    var targetName = '';
    var suggestions = [];
    var currentSugg = null;
    var footerLine = '';

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (!line || line.indexOf('----') !== -1) continue;

      if (line.indexOf('REPLACEMENT SUGGESTIONS for:') === 0) {
        targetName = line.replace('REPLACEMENT SUGGESTIONS for:', '').trim();
        continue;
      }
      if (line.indexOf('Reply with') === 0) {
        footerLine = line;
        continue;
      }

      var numMatch = line.match(/^(\\d+)\\.\\s+(.+)/);
      if (numMatch) {
        if (currentSugg) suggestions.push(currentSugg);
        var exName = numMatch[2];
        var isNew = exName.indexOf(' NEW') !== -1;
        if (isNew) exName = exName.replace(' NEW', '').trim();
        currentSugg = { num: numMatch[1], name: exName, isNew: isNew, volume: '', bodyPart: '', muscles: '', pattern: '' };
        continue;
      }
      if (currentSugg && line.match(/^\\d+\\s+rounds/i)) { currentSugg.volume = line; continue; }
      if (currentSugg && line.indexOf('Body Part Focus:') === 0) { currentSugg.bodyPart = line.replace('Body Part Focus:', '').trim(); continue; }
      if (currentSugg && line.indexOf('Muscles Worked:') === 0) { currentSugg.muscles = line.replace('Muscles Worked:', '').trim(); continue; }
      if (currentSugg && line.indexOf('Movement Pattern:') === 0) { currentSugg.pattern = line.replace('Movement Pattern:', '').trim(); continue; }
    }
    if (currentSugg) suggestions.push(currentSugg);
    if (suggestions.length === 0) return null;
    return { targetName: targetName, suggestions: suggestions, footerLine: footerLine };
  }

  function buildReplacementCard(data) {
    var html = '<div class="workout-card">';
    html += '<div class="workout-header">';
    html += '<h3>Replacement Suggestions</h3>';
    html += '<div class="workout-meta"><div class="meta-tag">Replacing: <span>' + escapeHtml(data.targetName) + '</span></div></div>';
    html += '</div>';
    html += '<div class="exercise-list">';
    for (var i = 0; i < data.suggestions.length; i++) {
      var s = data.suggestions[i];
      var volParts = s.volume.match(/(\\d+)\\s+rounds\\s+x\\s+(.+)/i);
      var rounds = volParts ? volParts[1] : '';
      var amount = volParts ? volParts[2] : s.volume;
      html += '<div class="exercise-row">';
      html += '<div class="ex-num">' + s.num + '</div>';
      html += '<div>';
      html += '<div class="ex-name">' + escapeHtml(s.name) + (s.isNew ? ' <span class="ex-new">new</span>' : '') + '</div>';
      html += '<div class="ex-details">';
      if (s.bodyPart) html += '<div class="ex-detail-tag"><span>Body Part Focus</span>' + escapeHtml(s.bodyPart) + '</div>';
      if (s.muscles) html += '<div class="ex-detail-tag"><span>Muscles Worked</span>' + escapeHtml(s.muscles) + '</div>';
      if (s.pattern) html += '<div class="ex-detail-tag"><span>Movement Pattern</span>' + escapeHtml(s.pattern) + '</div>';
      html += '</div></div>';
      html += '<div><div class="ex-volume">' + escapeHtml(amount) + '</div>';
      if (rounds) html += '<div class="ex-type">' + rounds + ' rounds</div>';
      html += '</div></div>';
    }
    html += '</div>';
    html += '<div class="workout-footer">';
    html += '<div class="reply-options">Pick a replacement</div>';
    html += '<div class="quick-replies">';
    for (var j = 0; j < data.suggestions.length; j++) {
      html += '<div class="quick-reply" onclick="sendQuick(\\'' + (j+1) + '\\')">' + (j+1) + '. ' + escapeHtml(data.suggestions[j].name) + '</div>';
    }
    html += '</div></div></div>';
    return html;
  }

  function parseWorkoutText(text) {
    // Detect if this is a workout suggestion
    if (text.indexOf('WORKOUT SUGGESTION') === -1 && text.indexOf('Focus:') === -1) {
      return null;
    }

    var lines = text.split('\\n');
    var focus = '', volume = '', patterns = '', equipment = '';
    var exercises = [];
    var inExercises = false;
    var currentEx = null;
    var footerLines = [];
    var inFooter = false;

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (!line || line.indexOf('----') !== -1 || line === 'WORKOUT SUGGESTION') continue;

      if (line.indexOf('Focus:') === 0) { focus = line.replace('Focus:', '').trim(); continue; }
      if (line.indexOf('Volume:') === 0) { volume = line.replace('Volume:', '').trim(); continue; }
      if (line.indexOf('Patterns:') === 0) { patterns = line.replace('Patterns:', '').trim(); continue; }
      if (line.indexOf('Equipment:') === 0) { equipment = line.replace('Equipment:', '').trim(); continue; }

      if (line.indexOf('Reply with:') !== -1) { inFooter = true; inExercises = false; continue; }
      if (inFooter) { if (line.indexOf('>') === 0) footerLines.push(line.replace('>', '').trim()); continue; }

      // Exercise number line: "1. Exercise Name"
      var numMatch = line.match(/^(\\d+)\\.\\s+(.+)/);
      if (numMatch) {
        if (currentEx) exercises.push(currentEx);
        var exName = numMatch[2];
        var isNew = exName.indexOf(' NEW') !== -1;
        if (isNew) exName = exName.replace(' NEW', '').trim();
        currentEx = { num: numMatch[1], name: exName, isNew: isNew, volume: '', bodyPart: '', muscles: '', intensity: '' };
        inExercises = true;
        continue;
      }

      // Volume line: "   3 rounds x 12 reps"
      if (inExercises && currentEx && line.match(/^\\d+\\s+rounds/i)) {
        currentEx.volume = line;
        continue;
      }
      if (inExercises && currentEx && line.indexOf('Body Part Focus:') === 0) {
        currentEx.bodyPart = line.replace('Body Part Focus:', '').trim();
        continue;
      }
      if (inExercises && currentEx && line.indexOf('Muscles Worked:') === 0) {
        currentEx.muscles = line.replace('Muscles Worked:', '').trim();
        continue;
      }
      if (inExercises && currentEx && line.indexOf('Movement Pattern:') === 0) {
        currentEx.intensity = line.replace('Movement Pattern:', '').trim();
        continue;
      }
    }
    if (currentEx) exercises.push(currentEx);

    if (exercises.length === 0) return null;

    return { focus: focus, volume: volume, patterns: patterns, equipment: equipment, exercises: exercises, footerLines: footerLines };
  }

  function buildWorkoutCard(data) {
    var html = '<div class="workout-card">';

    // Header
    html += '<div class="workout-header">';
    html += '<h3>Workout Suggestion</h3>';
    html += '<div class="workout-meta">';
    if (data.focus) html += '<div class="meta-tag"><span>Focus</span> ' + escapeHtml(data.focus) + '</div>';
    if (data.volume) html += '<div class="meta-tag"><span>Volume</span> ' + escapeHtml(data.volume) + '</div>';
    if (data.equipment) html += '<div class="meta-tag"><span>Equipment</span> ' + escapeHtml(data.equipment) + '</div>';
    html += '</div></div>';

    // Exercises
    html += '<div class="exercise-list">';
    for (var i = 0; i < data.exercises.length; i++) {
      var ex = data.exercises[i];
      // Parse volume into parts
      var volParts = ex.volume.match(/(\\d+)\\s+rounds\\s+x\\s+(.+)/i);
      var rounds = volParts ? volParts[1] : '';
      var amount = volParts ? volParts[2] : ex.volume;

      html += '<div class="exercise-row">';
      html += '<div class="ex-num">' + ex.num + '</div>';
      html += '<div>';
      html += '<div class="ex-name">' + escapeHtml(ex.name) + '</div>';
      if (ex.isNew) html += '<div class="ex-new">new</div>';
      html += '<div class="ex-details">';
      if (ex.bodyPart) html += '<div class="ex-detail-tag"><span>Body Part Focus</span>' + escapeHtml(ex.bodyPart) + '</div>';
      if (ex.muscles) html += '<div class="ex-detail-tag"><span>Muscles Worked</span>' + escapeHtml(ex.muscles) + '</div>';
      if (ex.intensity) html += '<div class="ex-detail-tag"><span>Movement Pattern</span>' + escapeHtml(ex.intensity) + '</div>';
      html += '</div>';
      html += '</div>';
      html += '<div><div class="ex-volume">' + escapeHtml(amount) + '</div>';
      if (rounds) html += '<div class="ex-type">' + rounds + ' rounds</div>';
      html += '</div>';
      html += '</div>';
    }
    html += '</div>';

    // Footer with quick replies
    if (data.footerLines.length > 0) {
      html += '<div class="workout-footer">';
      html += '<div class="reply-options">Reply with</div>';
      html += '<div class="quick-replies">';
      for (var j = 0; j < data.footerLines.length; j++) {
        var line = data.footerLines[j];
        html += '<div class="quick-reply" onclick="sendQuick(\\'' + line.replace(/'/g, "\\\\'") + '\\')">' + escapeHtml(line) + '</div>';
      }
      html += '</div></div>';
    }

    html += '</div>';
    return html;
  }

  function addBotMessage(text) {
    var div = document.createElement('div');
    div.className = 'message bot';

    var replacementParsed = parseReplacementSuggestions(text);
    if (replacementParsed) {
      div.innerHTML = '<div class="message-label">Workout Tracker</div>' + buildReplacementCard(replacementParsed);
      messagesEl.appendChild(div);
      scrollToBottom();
      return;
    }
    var parsed = parseWorkoutText(text);
    var content = '';

    if (parsed) {
      content = buildWorkoutCard(parsed);
    } else {
      // Plain text  -  check for success/error
      var isError = text.indexOf('ERROR') !== -1 || text.indexOf('error') !== -1;
      if (isError) {
        content = '<div class="error-bubble">' + escapeHtml(text) + '</div>';
      } else {
        content = '<div class="bubble"><div class="plain-text">' + escapeHtml(text) + '</div></div>';
      }
    }

    div.innerHTML = '<div class="message-label">Workout Tracker</div>' + content;
    messagesEl.appendChild(div);
    scrollToBottom();
  }

  // -- STAGED WORKOUT PERSISTENCE -----------------------------------
  var stagedWorkoutData = null;

  async function checkForStagedWorkout() {
    try {
      var response = await fetch(STAGED_API_URL + '?session_id=' + encodeURIComponent(sessionId));
      if (!response.ok) return;
      var data = await response.json();
      if (data && data.exercises_json && data.exercises_json.length > 2) {
        stagedWorkoutData = data;
        var banner = document.getElementById('staged-banner');
        if (banner) {
          banner.style.display = 'flex';
        }
      }
    } catch(e) {
      // Silent fail  -  no staged workout or API not available
    }
  }

  function viewStagedWorkout() {
    if (!stagedWorkoutData) return;
    var banner = document.getElementById('staged-banner');
    if (banner) banner.style.display = 'none';
    hideWelcome();

    var exercisesRaw = stagedWorkoutData.exercises_json;
    var jsonStart = exercisesRaw.indexOf('[');
    if (jsonStart >= 0) exercisesRaw = exercisesRaw.substring(jsonStart);
    var exercises = JSON.parse(exercisesRaw);
    var focus = stagedWorkoutData.body_part_focus || 'full body';

    var lines = [];
    lines.push('WORKOUT SUGGESTION');
    lines.push('-----------------------------');
    lines.push('Focus:     ' + focus.charAt(0).toUpperCase() + focus.slice(1));
    lines.push('Volume:    Same as last');
    lines.push('-----------------------------');
    lines.push('');
    for (var i = 0; i < exercises.length; i++) {
      var ex = exercises[i];
      var newTag = ex.is_new_exercise ? ' NEW' : '';
      lines.push((i + 1) + '. ' + ex.exercise_name + newTag);
      lines.push('   ' + ex.rounds + ' rounds x ' + ex.repetition_amount + ' ' + ex.repetition_type);
      lines.push('   Body Part Focus: ' + (ex.body_part || ''));
      lines.push('   Muscles Worked: ' + (ex.muscles_worked || ''));
      lines.push('   Movement Pattern: ' + (ex.movement_pattern || ''));
      lines.push('');
    }
    lines.push('-----------------------------');
    lines.push('Reply with:');
    lines.push('> Confirm');
    lines.push('> Replace [exercise] with [new exercise]');
    lines.push('> Suggest replacements for [exercise]');
    lines.push('> Add [exercise name]');
    lines.push('> Remove #N or [exercise name]');
    lines.push('> Regenerate');

    addBotMessage(lines.join('\\n'));
  }

  function dismissStagedWorkout() {
    var banner = document.getElementById('staged-banner');
    if (banner) banner.style.display = 'none';
    stagedWorkoutData = null;
    sessionId = resetSession();
  }

  // Check for staged workout on page load
  window.addEventListener('load', function() {
    checkForStagedWorkout();
  });

  async function sendMessage() {
    var text = input.value.trim();
    if (!text) return;

    input.value = '';
    input.style.height = 'auto';
    sendBtn.disabled = true;

    addUserMessage(text);
    var typingEl = addTyping();

    try {
      var response = await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatInput: text,
          sessionId: sessionId,
          action: 'sendMessage'
        })
      });

      removeTyping();

      if (!response.ok) {
        addBotMessage('ERROR: Could not reach the server. Please try again.');
        return;
      }

      var data = await response.json();

      // Extract message text from response
      var messageText = '';
      if (typeof data === 'string') {
        messageText = data;
      } else if (data.output) {
        messageText = data.output;
      } else if (data.response_text) {
        messageText = data.response_text;
      } else if (data.text) {
        messageText = data.text;
      } else {
        messageText = JSON.stringify(data);
      }

      // Unescape literal \\n sequences into real newlines
      messageText = messageText.replace(/\\n/g, String.fromCharCode(10));
      addBotMessage(messageText);

    } catch (err) {
      removeTyping();
      addBotMessage('ERROR: ' + err.message);
    } finally {
      sendBtn.disabled = false;
      input.focus();
    }
  }
</script>
